//! Static enum dispatch over the operator set.
//!
//! [`OperatorKind`] replaces the previous `Box<dyn Operator>` registry: each
//! operator becomes a variant, and [`OperatorKind::evaluate`] is a `match` that
//! calls the corresponding (zero-sized) operator struct's
//! [`Operator::evaluate`]. No vtable and no per-lookup heap allocation.
//!
//! The variant set is generated by the `operator_kind!` macro from a single
//! `Variant => StructPath` list so the enum and its dispatch arm stay in lockstep.

use super::Operator;
use crate::evaluator::context::BindingContext;
use crate::evaluator::operators::*;
use orbital_core_base::schema::sexpr::SExpression;

/// Generates the `OperatorKind` enum and its `evaluate` dispatch from a list of
/// `Variant => StructPath` entries. Each operator struct is zero-sized, so the
/// dispatch constructs a fresh value and forwards to `Operator::evaluate`.
macro_rules! operator_kind {
    ($( $variant:ident => $struct_path:path ),+ $(,)?) => {
        /// Stack-allocated operator handle. Dispatched by `match`, never boxed.
        // Variant names mirror their `*Op` operator structs 1:1 by design.
        #[allow(clippy::enum_variant_names)]
        #[derive(Debug, Clone, Copy)]
        pub enum OperatorKind {
            $( $variant, )+
            /// Compile-time composition placeholder; carries the operator name.
            BehaviorCompositionStubOp(&'static str),
            /// Agent-runtime operator placeholder; carries the operator name.
            AgentStubOp(&'static str),
        }

        impl OperatorKind {
            /// Evaluate this operator with the given arguments and context.
            #[inline]
            pub fn evaluate(
                &self,
                args: &[SExpression],
                ctx: &BindingContext,
            ) -> EvalResult {
                match self {
                    $( OperatorKind::$variant => $struct_path.evaluate(args, ctx), )+
                    OperatorKind::BehaviorCompositionStubOp(name) => {
                        BehaviorCompositionStubOp(name).evaluate(args, ctx)
                    }
                    OperatorKind::AgentStubOp(name) => AgentStubOp(name).evaluate(args, ctx),
                }
            }
        }
    };
}

